namespace iSlideAddIn;
public static class AlignmentManager
{
    public static void Align(string dir) { var a = AddInModule.PowerPointApp; if (a?.ActivePresentation == null) return; try { var sel = a.ActiveWindow.Selection; if (sel.Type != 2 || sel.ShapeRange.Count < 2) { W("Select 2+ shapes."); return; } dynamic sr = sel.ShapeRange; int n = sr.Count; float v; switch (dir) { case "left": v = sr[1].Left; for (int i = 1; i <= n; i++) sr[i].Left = v; break; case "center": float cx = 0; for (int i = 1; i <= n; i++) cx += sr[i].Left + sr[i].Width / 2; v = cx / n; for (int i = 1; i <= n; i++) sr[i].Left = v - sr[i].Width / 2; break; case "right": v = 0; for (int i = 1; i <= n; i++) v = Math.Max(v, sr[i].Left + sr[i].Width); for (int i = 1; i <= n; i++) sr[i].Left = v - sr[i].Width; break; case "top": v = sr[1].Top; for (int i = 1; i <= n; i++) sr[i].Top = v; break; case "middle": float cy = 0; for (int i = 1; i <= n; i++) cy += sr[i].Top + sr[i].Height / 2; v = cy / n; for (int i = 1; i <= n; i++) sr[i].Top = v - sr[i].Height / 2; break; case "bottom": v = 0; for (int i = 1; i <= n; i++) v = Math.Max(v, sr[i].Top + sr[i].Height); for (int i = 1; i <= n; i++) sr[i].Top = v - sr[i].Height; break; } } catch { } }
    public static void DistributeHorizontal() { var a = AddInModule.PowerPointApp; if (a?.ActivePresentation == null) return; try { var sel = a.ActiveWindow.Selection; if (sel.Type != 2 || sel.ShapeRange.Count < 3) { W("Select 3+ shapes."); return; } dynamic sr = sel.ShapeRange; int n = sr.Count; var s = new List<dynamic>(); for (int i = 1; i <= n; i++) s.Add(sr[i]); s.Sort((x, y) => ((float)x.Left).CompareTo((float)y.Left)); float tw = s[n - 1].Left + s[n - 1].Width - s[0].Left, sw = 0; foreach (var x in s) sw += x.Width; float gap = n > 1 ? (tw - sw) / (n - 1) : 0, px = s[0].Left; foreach (var x in s) { x.Left = px; px += x.Width + gap; } } catch { } }
    public static void DistributeVertical() { var a = AddInModule.PowerPointApp; if (a?.ActivePresentation == null) return; try { var sel = a.ActiveWindow.Selection; if (sel.Type != 2 || sel.ShapeRange.Count < 3) { W("Select 3+ shapes."); return; } dynamic sr = sel.ShapeRange; int n = sr.Count; var s = new List<dynamic>(); for (int i = 1; i <= n; i++) s.Add(sr[i]); s.Sort((x, y) => ((float)x.Top).CompareTo((float)y.Top)); float th = s[n - 1].Top + s[n - 1].Height - s[0].Top, sh = 0; foreach (var x in s) sh += x.Height; float gap = n > 1 ? (th - sh) / (n - 1) : 0, py = s[0].Top; foreach (var x in s) { x.Top = py; py += x.Height + gap; } } catch { } }
    static void W(string m) => System.Windows.Forms.MessageBox.Show(m, "iSlide", System.Windows.Forms.MessageBoxButtons.OK, System.Windows.Forms.MessageBoxIcon.Warning);
}
